        "created_at",
        "updated_at",
        "deleted_at",
    }

    mutable_columns = {
        "type",
        "name",
        "description",
        "embedding",
        "notes",
        "is_active",
        "updated_at",
        "deleted_at",
    }

    jsonb_columns = {"embedding"}

    # Makes it so this record is more easily publishable.
    def shorten(self):
        return {
            "id": self["id"],
            "type": self["type"],
            "name": self["name"],
        }

    def backfill_overwrite(self, description, embedding, is_active):
        if is_active and not (description and embedding):
            raise ValueError("description and embedding must be provided if is_active is True")

        self["description"] = description
        self["embedding"] = json.dumps(embedding)
        self["is_active"] = is_active
        self["updated_at"] = datetime.now()
